import{_ as e,o as t,c as r,ag as s}from"./chunks/framework.DEqXEGcv.js";const i="/images/issues/034/news-cover.jpg",o="/images/issues/034/news-platform.jpg",l="/images/issues/034/news-browser.jpg",n="/images/issues/034/news-oss.jpg",h="/images/issues/034/news-actions.jpg",c="/images/issues/034/news-linux.jpg",p="/images/issues/034/news-eu.jpg",m="/images/issues/034/world-rail.jpg",g="/images/issues/034/world-pentagon.jpg",u="/images/issues/034/world-gbt.jpg",d="/images/issues/034/world-aindubai.jpg",_="/images/issues/034/world-ship.jpg",b="/images/issues/034/tool-otel.jpg",f="/images/issues/034/tool-git.jpg",q="/images/issues/034/tool-playwright.jpg",k="/images/issues/034/tool-scorecard.jpg",x="/images/issues/034/recommend.jpg",T=JSON.parse('{"title":"小七的周刊（第 034 期）：把复杂系统交给可观察的边界","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"小七的周刊（第 034 期）：把复杂系统交给可观察的边界"}],["meta",{"property":"og:description","content":"从平台工程、浏览器自动化到开源维护，讨论如何让复杂系统更容易被理解、验证和修复。"}],["meta",{"property":"og:image","content":"/images/issues/034/news-cover.jpg"}],["meta",{"property":"og:image:alt","content":"第 034 期封面图：正在运行的计算设备"}],["meta",{"property":"og:url","content":"https://blog.leeseven.com/issues/issue-034"}]]},"headers":[],"relativePath":"issues/issue-034.md","filePath":"issues/issue-034.md","lastUpdated":1792969978000}'),P={name:"issues/issue-034.md"};function w(y,a,j,A,S,v){return t(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="小七的周刊-第-034-期-把复杂系统交给可观察的边界" tabindex="-1">小七的周刊（第 034 期）：把复杂系统交给可观察的边界 <a class="header-anchor" href="#小七的周刊-第-034-期-把复杂系统交给可观察的边界" aria-label="Permalink to &quot;小七的周刊（第 034 期）：把复杂系统交给可观察的边界&quot;">​</a></h1><p><em>这里记录每周值得分享的科技内容，<strong>每周一发布</strong>（北京时间 07:00）。</em></p><h2 id="本期-3-个要点" tabindex="-1">本期 3 个要点 <a class="header-anchor" href="#本期-3-个要点" aria-label="Permalink to &quot;本期 3 个要点&quot;">​</a></h2><ol><li><strong>复杂不是问题，黑箱才是</strong>：系统可以很大，但关键边界必须能被检查、解释和回滚。</li><li><strong>自动化要留下证据</strong>：速度之外，日志、差异、来源和失败路径决定了它是否值得信任。</li><li><strong>工具选择应从约束出发</strong>：先明确要减少哪一种风险，再决定是否引入新的平台。</li></ol><h2 id="封面图" tabindex="-1">封面图 <a class="header-anchor" href="#封面图" aria-label="Permalink to &quot;封面图&quot;">​</a></h2><p><img src="'+i+'" alt="计算设备"></p><p>封面图：真实计算设备的局部照片。系统越复杂，越需要把不可见的过程转成可观察信号。</p><h2 id="本周短谈" tabindex="-1">本周短谈 <a class="header-anchor" href="#本周短谈" aria-label="Permalink to &quot;本周短谈&quot;">​</a></h2><h3 id="_1-平台工程的价值是减少认知负担" tabindex="-1">1. 平台工程的价值是减少认知负担 <a class="header-anchor" href="#_1-平台工程的价值是减少认知负担" aria-label="Permalink to &quot;1. 平台工程的价值是减少认知负担&quot;">​</a></h3><p><img src="'+o+'" alt="平台工程现场"></p><p>平台工程常被描述成“给开发者一条黄金路径”，但真正的价值不在于再做一个门户，而在于把部署、权限、依赖和回滚的默认选择写进流程。开发者仍然可以偏离路径，只是偏离时要知道代价。对小团队来说，先统一日志、配置和发布检查，比建设完整平台更实际。</p><h3 id="_2-浏览器自动化最怕成功得太安静" tabindex="-1">2. 浏览器自动化最怕成功得太安静 <a class="header-anchor" href="#_2-浏览器自动化最怕成功得太安静" aria-label="Permalink to &quot;2. 浏览器自动化最怕成功得太安静&quot;">​</a></h3><p><img src="'+l+'" alt="浏览器自动化"></p><p>自动化脚本跑完并不等于任务完成。页面可能加载了旧数据，点击可能落在错误的元素上，结果也可能没有被保存。把关键断言、截图和失败重试写进流程，才能把“看起来成功”变成可以复核的结果。边界在于，端到端测试不应替代单元测试，而应覆盖真正的用户路径。</p><h3 id="_3-开源维护需要可见的负担分配" tabindex="-1">3. 开源维护需要可见的负担分配 <a class="header-anchor" href="#_3-开源维护需要可见的负担分配" aria-label="Permalink to &quot;3. 开源维护需要可见的负担分配&quot;">​</a></h3><p><img src="'+n+'" alt="开源维护现场"></p><p>一个项目是否健康，不只看 stars 或最近一次发布，还要看 issue 是否有人响应、依赖是否更新、贡献者是否集中在一个人身上。使用开源软件时，给关键依赖留出升级和替换预算，往往比临时寻找“绝对安全”的项目更可靠。</p><h2 id="科技与-ai-动态" tabindex="-1">科技与 AI 动态 <a class="header-anchor" href="#科技与-ai-动态" aria-label="Permalink to &quot;科技与 AI 动态&quot;">​</a></h2><h3 id="_1-github-actions-强化可复用工作流" tabindex="-1">1. <a href="https://github.blog/changelog/" target="_blank" rel="noreferrer">GitHub Actions 强化可复用工作流</a> <a class="header-anchor" href="#_1-github-actions-强化可复用工作流" aria-label="Permalink to &quot;1. [GitHub Actions 强化可复用工作流](https://github.blog/changelog/)&quot;">​</a></h3><p><img src="'+h+'" alt="代码托管工作流"></p><p>【事实】GitHub 持续扩展 Actions 的复用、权限和执行能力，让团队可以把重复的构建和检查抽成工作流。它降低了复制配置的成本，也把权限继承和凭证暴露带进了新的审查范围。</p><p>【推测】真正值得关注的不是步骤变少，而是默认权限是否足够窄。建议从一个低风险仓库开始，检查工作流 token、第三方 action 来源和日志中的秘密。</p><h3 id="_2-linux-内核持续推进可维护性" tabindex="-1">2. <a href="https://www.kernel.org/" target="_blank" rel="noreferrer">Linux 内核持续推进可维护性</a> <a class="header-anchor" href="#_2-linux-内核持续推进可维护性" aria-label="Permalink to &quot;2. [Linux 内核持续推进可维护性](https://www.kernel.org/)&quot;">​</a></h3><p><img src="'+c+'" alt="Linux 开发现场"></p><p>【事实】Linux 内核仍通过公开邮件列表、代码审查和稳定分支协作，维持一个规模极大的软件项目。公开审查让变更过程可追踪，也意味着贡献者需要理解项目的协作边界。</p><p>【推测】对普通团队而言，最值得借鉴的是“小变更、可回溯、有人负责”的节奏，而不是照搬内核的工具链。</p><h3 id="_3-欧盟-ai-act-进入分阶段执行" tabindex="-1">3. <a href="https://digital-strategy.ec.europa.eu/en/policies/regulatory-framework-ai" target="_blank" rel="noreferrer">欧盟 AI Act 进入分阶段执行</a> <a class="header-anchor" href="#_3-欧盟-ai-act-进入分阶段执行" aria-label="Permalink to &quot;3. [欧盟 AI Act 进入分阶段执行](https://digital-strategy.ec.europa.eu/en/policies/regulatory-framework-ai)&quot;">​</a></h3><p><img src="'+p+'" alt="政策会议现场"></p><p>【事实】欧盟 AI Act 采取分阶段生效方式，对不同风险等级的系统提出不同要求。具体义务取决于应用场景、供应链位置和投放地区，不能只凭“用了模型”这一点判断。</p><p>【推测】产品团队应先建立模型、数据和用户场景清单，再判断哪些记录需要长期保存。早做映射，通常比临上线前补文档成本更低。</p><h2 id="世界之最" tabindex="-1">世界之最 <a class="header-anchor" href="#世界之最" aria-label="Permalink to &quot;世界之最&quot;">​</a></h2><h3 id="_1-世界最快的商业磁悬浮列车-上海磁浮" tabindex="-1">1. 世界最快的商业磁悬浮列车：上海磁浮 <a class="header-anchor" href="#_1-世界最快的商业磁悬浮列车-上海磁浮" aria-label="Permalink to &quot;1. 世界最快的商业磁悬浮列车：上海磁浮&quot;">​</a></h3><p><img src="'+m+'" alt="上海磁浮列车"><em>上海磁浮展示了高速交通系统对轨道、控制和维护的综合要求。</em> 极限速度依赖整套系统协同，而不是单个部件。软件性能优化也应同时检查监控、降级和维护成本。</p><h3 id="_2-世界最大的办公楼之一-五角大楼" tabindex="-1">2. 世界最大的办公楼之一：五角大楼 <a class="header-anchor" href="#_2-世界最大的办公楼之一-五角大楼" aria-label="Permalink to &quot;2. 世界最大的办公楼之一：五角大楼&quot;">​</a></h3><p><img src="'+g+'" alt="五角大楼"><em>五角大楼容纳数万人办公，内部走廊总长超过 28 公里。</em> 把数万人放进一栋楼，靠的不是更大的空间，而是清晰的分区和通行规则。系统扩容同理，边界和路由比容量数字更重要。</p><h3 id="_3-世界最大的全可动射电望远镜-绿岸望远镜" tabindex="-1">3. 世界最大的全可动射电望远镜：绿岸望远镜 <a class="header-anchor" href="#_3-世界最大的全可动射电望远镜-绿岸望远镜" aria-label="Permalink to &quot;3. 世界最大的全可动射电望远镜：绿岸望远镜&quot;">​</a></h3><p><img src="'+u+'" alt="绿岸望远镜"><em>绿岸望远镜口径 100 米，整面天线可以机械转动跟踪目标。</em> 可动结构带来灵活性，也带来维护和校准成本。自动化系统也一样，自由度越高，越需要可验证的状态。</p><h3 id="_4-世界最高的摩天轮-迪拜眼" tabindex="-1">4. 世界最高的摩天轮：迪拜眼 <a class="header-anchor" href="#_4-世界最高的摩天轮-迪拜眼" aria-label="Permalink to &quot;4. 世界最高的摩天轮：迪拜眼&quot;">​</a></h3><p><img src="'+d+'" alt="迪拜眼摩天轮"><em>迪拜眼高约 250 米，轮辐和轿厢要在海风中长期保持稳定。</em> 高度带来的不是单点突破，而是风载、结构和运维的持续平衡。性能优化同样要看长期稳定性，而不是峰值数字。</p><h3 id="_5-世界最大的集装箱船之一-emma-maersk" tabindex="-1">5. 世界最大的集装箱船之一：Emma Maersk <a class="header-anchor" href="#_5-世界最大的集装箱船之一-emma-maersk" aria-label="Permalink to &quot;5. 世界最大的集装箱船之一：Emma Maersk&quot;">​</a></h3><p><img src="'+_+'" alt="集装箱船"><em>大型集装箱船把成千上万件货物放进可追踪的运输网络。</em> 当对象数量变多，命名、索引和状态记录会成为基础能力。软件资产管理也是同一个问题。</p><h2 id="工具深挖" tabindex="-1">工具深挖 <a class="header-anchor" href="#工具深挖" aria-label="Permalink to &quot;工具深挖&quot;">​</a></h2><h3 id="_1-opentelemetry-把观测信号统一起来" tabindex="-1">1. <a href="https://opentelemetry.io/" target="_blank" rel="noreferrer">OpenTelemetry：把观测信号统一起来</a> <a class="header-anchor" href="#_1-opentelemetry-把观测信号统一起来" aria-label="Permalink to &quot;1. [OpenTelemetry：把观测信号统一起来](https://opentelemetry.io/)&quot;">​</a></h3><p><img src="'+b+'" alt="观测工具终端"> OpenTelemetry 统一 traces、metrics 和 logs 的采集语义，适合已经跨多个服务、开始难以定位问题的团队。它不是自动诊断器，落地前要先定义关键请求和服务边界，否则只会得到更多数据。</p><h3 id="_2-git-让每次改变都有出处" tabindex="-1">2. <a href="https://git-scm.com/" target="_blank" rel="noreferrer">Git：让每次改变都有出处</a> <a class="header-anchor" href="#_2-git-让每次改变都有出处" aria-label="Permalink to &quot;2. [Git：让每次改变都有出处](https://git-scm.com/)&quot;">​</a></h3><p><img src="'+f+'" alt="Git 工具"> Git 的价值不只是保存代码，更是让变更可以比较、讨论和撤销。团队不必追求每次提交都完美，但应避免把多个无关动作压成一个无法解释的大提交。</p><h3 id="_3-playwright-验证真实浏览器路径" tabindex="-1">3. <a href="https://playwright.dev/" target="_blank" rel="noreferrer">Playwright：验证真实浏览器路径</a> <a class="header-anchor" href="#_3-playwright-验证真实浏览器路径" aria-label="Permalink to &quot;3. [Playwright：验证真实浏览器路径](https://playwright.dev/)&quot;">​</a></h3><p><img src="'+q+'" alt="浏览器测试工具"> Playwright 适合覆盖登录、表单、支付等用户真正会走过的路径。它的成本是运行时间和测试维护，建议只把高价值流程放进端到端层，其他逻辑留在更快的测试里。</p><h3 id="_4-openssf-scorecard-检查开源依赖信号" tabindex="-1">4. <a href="https://github.com/ossf/scorecard" target="_blank" rel="noreferrer">OpenSSF Scorecard：检查开源依赖信号</a> <a class="header-anchor" href="#_4-openssf-scorecard-检查开源依赖信号" aria-label="Permalink to &quot;4. [OpenSSF Scorecard：检查开源依赖信号](https://github.com/ossf/scorecard)&quot;">​</a></h3><p><img src="'+k+'" alt="依赖检查"> Scorecard 可以帮助团队快速查看分支保护、危险工作流和依赖维护等信号。分数只能作为起点，不能替代对项目用途、版本和维护者响应速度的判断。</p><h2 id="本周冷知识-彩蛋" tabindex="-1">本周冷知识 / 彩蛋 <a class="header-anchor" href="#本周冷知识-彩蛋" aria-label="Permalink to &quot;本周冷知识 / 彩蛋&quot;">​</a></h2><ul><li>🥚 <strong>冷知识</strong>：可观测性里的 trace 原本就是“轨迹”的意思，重点不是记录更多，而是把一次请求经过的路径串起来。</li><li>🧠 <strong>彩蛋</strong>：Git 的对象模型用内容寻址保存数据，所以同一内容在不同引用关系中仍可被识别为同一个对象。</li></ul><h2 id="小七的碎碎念" tabindex="-1">小七的碎碎念 <a class="header-anchor" href="#小七的碎碎念" aria-label="Permalink to &quot;小七的碎碎念&quot;">​</a></h2><p>我越来越相信，成熟系统的魅力不是“什么都不会坏”，而是坏了以后能很快告诉你坏在哪里。自动化如果只负责把按钮按下去，最后还是会把解释工作留给人类。</p><h2 id="意外推荐-非科技" tabindex="-1">意外推荐（非科技） <a class="header-anchor" href="#意外推荐-非科技" aria-label="Permalink to &quot;意外推荐（非科技）&quot;">​</a></h2><p><strong>《降临》</strong>（电影）</p><p><img src="'+x+'" alt="《降临》电影海报"></p><p>它把“理解一个系统”拍成了耐心的工作：先建立共同语言，再判断下一步。技术团队处理复杂需求时，也常常不是缺少聪明人，而是缺少共享的上下文。</p><h2 id="互动钩子" tabindex="-1">互动钩子 <a class="header-anchor" href="#互动钩子" aria-label="Permalink to &quot;互动钩子&quot;">​</a></h2><blockquote><p><strong>本周问题：你所在的项目里，哪一个“看似自动完成”的步骤最需要补一条可验证证据？</strong></p></blockquote><h2 id="本周行动清单" tabindex="-1">本周行动清单 <a class="header-anchor" href="#本周行动清单" aria-label="Permalink to &quot;本周行动清单&quot;">​</a></h2><ul><li>[ ] 为一个关键流程补充成功断言、失败日志和可撤销动作。</li><li>[ ] 检查一个 CI 工作流的默认权限与第三方 action 来源。</li><li>[ ] 给一个关键开源依赖建立版本、维护状态和替换成本记录。</li><li>[ ] 选一条真实用户路径加入浏览器自动化测试。</li></ul><div class="issue-subscribe-cta"><h3 id="📬-喜欢这期内容" tabindex="-1">📬 喜欢这期内容？ <a class="header-anchor" href="#📬-喜欢这期内容" aria-label="Permalink to &quot;📬 喜欢这期内容？&quot;">​</a></h3><p>订阅「小七的周刊」，每周一收到最新一期。</p><div class="issue-cta-buttons"><a href="/feed.xml" class="cta-rss" target="_blank" rel="noopener noreferrer">RSS 订阅</a><a href="https://github.com/leeseven1211/blog-weekly" class="cta-share" target="_blank" rel="noopener noreferrer">GitHub</a></div></div>',63)])])}const I=e(P,[["render",w]]);export{T as __pageData,I as default};
